import json
import requests
"""
Access key https://wft.int.net.nokia.com/ALL/profile
"""

WFT_API_ADDR = 'https://wft.int.net.nokia.com:8091/api/v1/'
WFT_API_SEARCH_ADDR = 'https://wft.int.net.nokia.com:8091/SBTS/api/v1/'
ACCESS_KEY = 'q4fV0iZlcMi7J4LqZ9OLBVcUpWzLabfJ0KSqKXV0'


class WftApi(object):
    """
    WFT Web API.
    """

    def __init__(self, project, component, version):
        self.project = project
        self.component = component
        self.version = version

        self._url = "{api_addr}{project}/{component}/builds/{version}.json".format(
            api_addr=WFT_API_ADDR,
            project=self.project,
            component=self.component,
            version=self.version
        )

        self._url_newest = "{api_addr}{project}.json".format(
            api_addr=WFT_API_SEARCH_ADDR,
            project=self.project
        )

    def get_branch(self):
        self._url = "{}?items[]=sub_builds&access_key={}".format(
            self._url, ACCESS_KEY
        )
        resp = requests.get(self._url, params='id')
        self._check_response(resp)
        return json.loads(resp.content)

    @staticmethod
    def _check_response(resp):
        if not resp.ok:
            msg = (
                'endpoint returned bad response: '
                '"({response.status_code}) {response.reason}".'
            )
            msg = msg.format(response=resp)
            raise WftApiError(msg)

    def get_newest_released_branch_name(self):
        self._url_newest = "{url}build_branch.json?access_key={akey}" \
                    "&view[items]=50" \
                    "&view[sorting_field]=created_at" \
                    "&view[sorting_direction]=DESC" \
                    "&view[columns[][id]]=version" \
                    "&view[columns[][id]]=quicktest_status" \
                    "&view[view_filters_attributes[1]][column]=branch.title" \
                    "&view[view_filters_attributes[1]][operation]=eq" \
                    "&view[view_filters_attributes[1]][value][]={comp}&".format(url=WFT_API_SEARCH_ADDR,
                                                                                akey=ACCESS_KEY,
                                                                                comp=self.component)
        resp = requests.get(self._url_newest)
        self._check_response(resp)
        resp_cont = resp.content
        items = json.loads(resp_cont)['items']
        released_fsm3_branches = []
        for item in items:
            if item['quicktest_status']['state'] == 'released':
                released_fsm3_branches.append(item['version'])
        return released_fsm3_branches[0]


class WftApiError(Exception):
    """ WftApiError Raised when any error occurred. """
